import{z as B,x as A,o as e,c as s,q as t,j as n,D as E,d as i,s as l,S as o}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"队列不平衡因子","description":"","frontmatter":{"title":"队列不平衡因子","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/queue-imbalance-alpha.md","filePath":"quant/queue-imbalance-alpha.md","lastUpdated":1791413859000}'),p={name:"quant/queue-imbalance-alpha.md"};function I(_,a,d,h,u,m){const r=A("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="队列不平衡因子" tabindex="-1">队列不平衡因子 <a class="header-anchor" href="#队列不平衡因子" aria-label="Permalink to &quot;队列不平衡因子&quot;">​</a></h1><div class="epigraph"><p>最优档两侧排队量的相对厚度，会改变下一笔主动单打穿哪一边的概率；把这个厚度差做成短窗因子，预测的是簿的几何，不是一个新的风险溢价。</p><footer>—— 据 Cont, Kukanov, Stoikov 对订单簿事件与价格冲击的研究，以及 Harris 对深度与价格压力的论述整理</footer></div><p><a href="/quant/order-imbalance">盘口不平衡</a> 已经把两侧量差收成标量 \\(I\\)。本篇把它写成可交易研究里的<strong>因子</strong>：在事件时间或极短日历窗上，用最优档（或前几档）队列不平衡预测下一跳中间价或下一笔成交方向，并交代它与 <a href="/quant/ofi-toxicity">订单流毒性</a> 的 OFI、与 <a href="/quant/cancel-queue-position">撤单和队列位置</a> 的关系。它不是 Amihud 或 Fama–French 那种日频截面溢价；持有期按毫秒到秒计，边来自谁先看到簿的不对称，成本来自自己的挂单也会改写队列。Cont 等人证明簿事件线性推动中点；队列不平衡是这些事件积分之后的<strong>存量状态</strong>。Harris 强调可见深度本身构成价格压力。二者合在一起，才允许把 \\(I\\) 当作短窗 alpha 的候选，而不是深度的装饰性图表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>中间价把买卖对称看待，但 FIFO 队列并不对称：卖档薄，随机到来的主动买更容易抬高 \\(a_1\\)；买档薄则相反。于是当前快照</p> \\[I_1=\\frac{q^b_1-q^a_1}{q^b_1+q^a_1} \\]<p>对下一步 \\(\\Delta m\\) 与下一步主动方向都有预测力。问题是：这点预测力在扣掉延迟、手续费与自成交冲击之后还剩多少，以及它究竟是可重复的微观结构边，还是对瞬时深度的样本内拟合。</p><p>第二个问题是与流量因子分工。OFI 是窗内净事件；\\(I_1\\) 是窗末状态。两者高度相关：正的 OFI 会把 \\(I_1\\) 推高。若研究里同时放进回归还声称「两个独立 alpha」，多半是共线。需要先写清：用状态还是用流量、预测哪一个因变量、在哪一种时钟上持有。</p><h3 id="存量队列不平衡不是流量-ofi" tabindex="-1">存量队列不平衡不是流量 OFI <a class="header-anchor" href="#存量队列不平衡不是流量-ofi" aria-label="Permalink to &quot;存量队列不平衡不是流量 OFI&quot;">​</a></h3><p>\\(I_1\\) 只使用此刻可见的最优档量，计算廉价，不依赖消息分类。OFI 依赖把每条消息标成买向或卖向，分类错误直接进因子。预测「下一笔成交方向」时，当前 \\(I_1\\) 往往足够：对手方更薄的一侧更可能被打穿。预测「接下来 500 毫秒的中点收益」时，窗内累积 OFI 通常更强，因为状态可能在窗内已被新的增撤改写。方法上不要用五分钟 bar 的收盘 \\(I_1\\) 去预测次日收益——那已经离开微观结构，并与隔夜跳空、公告混在一起。</p><p><span class="marginnote">微价格把 \\(I_1\\) 嵌进价格读数，见 <a href="/quant/microprice">微观价格</a>。队列不平衡因子用 \\(I_1\\) 本身当自变量；二者不要同时进入同一回归还解释成正交。</span></p><p><span class="marginnote">「队列不平衡」可以翻译成盘口的「兵力对比」：买一档与卖一档各堆了多少量。比如买一挂 8,000 股、卖一挂 2,000 股，\\(I_1=(8000-2000)/(8000+2000)=0.6\\)——买侧明显更厚，卖档相对薄，下一跳向上碰卖价的概率更大。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义必须锁死档位 \\(K\\)、是否对远档衰减、分母是否加平滑以免档量接近零时 \\(I\\) 乱跳。\\(K=1\\) 对下一跳最敏感；\\(K=5\\) 更稳、更慢。时钟用簿事件或固定的几十到几百毫秒；标签用下一事件的 \\(\\mathrm{sign}(\\Delta m)\\) 或下一笔主动方向。评估应在事件时间上算命中率与均值收益，并报告对应的中位墙钟间隔，避免把清淡时段的空步当成许多独立样本。</p><p>样本分割要按日历日或按交易时段，而不是随机打散事件：同一秒内的相邻事件强相关，随机切分会泄漏。延迟方面，回测必须把 \\(I_1\\) 的时间戳加上行情到决策的滞后，再用当时可成交的 BBO 估价；用同一毫秒的快照「预测」同一毫秒的中点，不是因子，是恒等式的边角。自己的限价单应计入模拟簿，否则会以为总能站在厚的一侧排队。</p><h3 id="短窗预测与自成交冲击" tabindex="-1">短窗预测与自成交冲击 <a class="header-anchor" href="#短窗预测与自成交冲击" aria-label="Permalink to &quot;短窗预测与自成交冲击&quot;">​</a></h3><p>把 \\(I_1\\) 当成信号去吃薄侧，吃单本身就是 OFI，立刻修正 \\(I_1\\)，中点向你不利的方向跳。这是 Kyle 式冲击在限价簿上的微观版本：你不能在不动价格的前提下兑现全部可预测性。更自然的用法是<strong>选边挂单</strong>：买压厚时更愿意在买档排队（更高的填成、但更差的逆向选择），或在卖档更保守。评估必须用队列位置与实现价差，而不是只用中点方向的命中率。命中率高但每次都当 taker 吃薄侧，净边可以为负。</p><p>截面上把许多标的的 \\(I_1\\) 拿去排序做成「日频因子」，时间尺度错了。若一定要加总，应先在日内把短窗收益累加，再谈跨股比较；tick 大小、价位水平不同，\\(I_1\\) 的可比较性仍有限。这与 <a href="/quant/amihud-illiquidity">Amihud 非流动性</a> 那种日度冲击代理不是同一类对象。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>几何机制不需要知情者：\\(I_1\\gt 0\\) 意味着卖档相对薄，中点的条件期望上偏。信息机制是：愿意在买档暴露深度、或把卖档撤薄，可能声明看涨，于是 \\(I_1\\) 与后续收益同向。几十毫秒内第一种足够解释大部分可预测性；持续许多秒的 \\(I_1\\) 才更像需求或信息，并与毒性、<a href="/quant/vpin">VPIN</a> 开始相关。</p><p>队头与队尾的量对因子含义不同。队头厚，下一笔成交先碰到它，几何预测更真；队尾厚只是远处挂单，随时可撤，对下一跳贡献小。L2 把二者加总进 \\(q_1\\)，因子被可撤的队尾稀释。L3 若能把队头若干量单独做成 \\(I_{\\mathrm{head}}\\)，通常更干净。取消率高时，\\(I_1\\) 的半衰期只有若干事件，因子必须高频更新，日终一个快照没有意义。</p>',21)),(e(),n(o,null,{default:E(()=>[l(r,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20DISP%5B%22%E5%8F%AF%E8%A7%81%20L2%20%E6%A1%A3%E9%87%8F%20q%22%5D%20--%3E%20HEAD%5B%22%E9%98%9F%E5%A4%B4%E9%87%8F%EF%BC%9A%E5%85%88%E8%A2%AB%E6%88%90%E4%BA%A4%E7%A2%B0%E5%88%B0%22%5D%0A%20%20DISP%20--%3E%20TAIL%5B%22%E9%98%9F%E5%B0%BE%E9%87%8F%EF%BC%9A%E9%9A%8F%E6%97%B6%E5%8F%AF%E6%92%A4%22%5D%0A%20%20HEAD%20--%3E%20CLEAN%5B%22%E5%AF%B9%E4%B8%8B%E4%B8%80%E8%B7%B3%E7%9A%84%E5%87%A0%E4%BD%95%E9%A2%84%E6%B5%8B%E6%9B%B4%E7%9C%9F%22%5D%0A%20%20TAIL%20--%3E%20DIL%5B%22%E7%A8%80%E9%87%8A%20I%EF%BC%9A%E5%8F%AF%E6%92%A4%E9%87%8F%E6%B7%B7%E8%BF%9B%E9%98%9F%E5%88%97%22%5D%0A%20%20HIDE%5B%22%E5%86%B0%E5%B1%B1%E9%9A%90%E8%97%8F%E8%A1%A5%E9%87%8F%22%5D%20--%3E%20BIAS%5B%22%E6%98%BE%E7%A4%BA%E9%87%8F%E5%81%8F%E5%B0%8F%EF%BC%9AI%20%E5%81%87%E8%A3%85%E4%B8%80%E4%BE%A7%E8%96%84%22%5D%0A%20%20DARK%5B%22%E6%9A%97%E6%B1%A0%E6%88%90%E4%BA%A4%22%5D%20--%3E%20LAG%5B%22%E9%9C%80%E6%B1%82%E5%B7%B2%E8%A2%AB%E5%8C%B9%E9%85%8D%EF%BC%8C%E6%9C%AC%E5%9C%B0%20I%20%E6%BB%9E%E5%90%8E%22%5D%0A%20%20CLEAN%20--%3E%20FIX%5B%22L3%20%E5%8D%95%E5%88%97%E9%98%9F%E5%A4%B4%E9%87%8F%EF%BC%9AI_head%20%E6%9B%B4%E5%B9%B2%E5%87%80%22%5D%0A%20%20DIL%20--%3E%20FIX%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">直觉类比：排队买奶茶。队头是站在窗口前的那三个人，下一杯一定从他们出；队尾是排在街角、随时可能走开的一群人。L2 只告诉你「这家店一共排了 30 人」，分不清哪些真会等到——把队尾当需求，就高估了队伍的硬度。</span></p><h3 id="冰山补量与可见队列的偏差" tabindex="-1">冰山补量与可见队列的偏差 <a class="header-anchor" href="#冰山补量与可见队列的偏差" aria-label="Permalink to &quot;冰山补量与可见队列的偏差&quot;">​</a></h3><p>冰山让显示的 \\(q^a_1\\) 偏小，\\(I_1\\) 偏向「卖侧薄、中点将涨」，而隐藏卖量正在吸收主动买。统计上会看到：高 \\(I_1\\) 之后中点并不涨、或涨完立刻被压回，同时同价位出现新的卖限价。研究可以把「耗尽后短时补量」当作隐藏深度的代理，修正 \\(I_1\\) 的测量误差。这是为了理解可见因子为何失效，不是为了构造一层误导性的展示量去吸引对手。暗池成交则根本不进入 \\(q^b,q^a\\)，本地 \\(I_1\\) 会在需求已被匹配后仍显示不平衡。</p><p><span class="marginnote">监管关注的虚假申报，核心是展示与真实成交意愿系统性背离。微观结构因子研究应当把高取消率拆成存货型改价与潜在误导，而不是把「取消多」写成策略建议。本篇只讨论可见队列作为预测变量的偏差来源。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>涨跌停板上 \\(I_1\\) 极端但不预测下一 tick，价格被制度钉住。集合竞价没有连续 FIFO 的同一含义。pro-rata 市场「队列」不是严格队头，不平衡对填成的映射改变。多市场时本地 \\(I_1\\) 忽略他处更优价格。最小报价单位很大时，量堆在一档，\\(I_1\\) 缓慢；tick 很小时 \\(I_1\\) 抖动，需要事件时间平滑。</p><p>预测力不等于 alpha。延迟、手续费、排队被选中的逆向选择、以及信号衰减，通常吃掉朴素回测的大部分。不要把队列不平衡写进低频风险模型；也不要用它去替代 <a href="/quant/pin">PIN</a> 的日度信息风险。<a href="/quant/kyle-lambda">Kyle lambda</a> 估的是流量对价格的斜率，本因子估的是存量几何对下一跳的条件概率，回归元不同。</p><p><span class="marginnote">常见误区：把命中率当净收益。回测里 \\(I_1\\) 对下一跳方向可能命中 55%，但若每次都当 taker 去吃薄侧，价差加冲击往往超过那 5 个百分点的优势；正确评估要用队列位置、实现价差与手续费，而不是只数中点方向对了几次。</span></p><p><span class="marginnote">\\(I_1\\to\\pm 1\\) 时一侧档量趋零，因子变成「这一档即将消失」的脆弱指标，而不是大单压力。应用上应同时保留 \\(q^b_1+q^a_1\\) 作为规模特征，或对极薄样本单独处理。</span></p>',9)),(e(),n(o,null,{default:E(()=>[l(r,{id:"mermaid-87",class:"mermaid",graph:"flowchart%20TD%0A%20%20Qb%5B%22%E4%B9%B0%E4%B8%80%E9%98%9F%E5%88%97%20q%5Eb%22%5D%20--%3E%20I%5B%22I%20%3D%20(q%5Eb%20-%20q%5Ea)%2F(q%5Eb%20%2B%20q%5Ea)%22%5D%0A%20%20Qa%5B%22%E5%8D%96%E4%B8%80%E9%98%9F%E5%88%97%20q%5Ea%22%5D%20--%3E%20I%0A%20%20I%20--%3E%20Dir%5B%22%E9%A2%84%E6%B5%8B%E4%B8%8B%E4%B8%80%E8%B7%B3%E6%96%B9%E5%90%91%20%2F%20%E4%B8%BB%E5%8A%A8%E8%BE%B9%22%5D%0A%20%20OFI%5B%22%E7%AA%97%E5%86%85%20OFI%22%5D%20--%3E%20I%0A%20%20I%20--%3E%20Quote%5B%22%E9%80%89%E8%BE%B9%E6%8C%82%E5%8D%95%22%5D%0A%20%20I%20--%3E%20Take%5B%22%E5%90%83%E8%96%84%E4%BE%A7%3A%20%E8%87%AA%E6%88%90%E4%BA%A4%E5%86%B2%E5%87%BB%22%5D%0A%20%20Ice%5B%22%E5%86%B0%E5%B1%B1%E8%A1%A5%E9%87%8F%22%5D%20-.-%3E%7C%22%E5%8F%AF%E8%A7%81%20q%20%E6%9C%89%E5%81%8F%22%7C%20I%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>队列不平衡因子是短窗、事件时间上的存量 \\(I\\)，预测下一跳几何，不是日频风险溢价。</li><li>它与 OFI 共线：一个是状态，一个是流量；不要并进回归还当两个故事。</li><li>可研究的用法偏选边挂单；taker 吃薄侧会改写 \\(I\\) 并支付冲击。</li><li>L2 分不清队头与可撤队尾；冰山与暗池使可见 \\(I\\) 有偏，检测属测量研究。</li><li>延迟、制度时段、tick 与自成交决定朴素命中率还剩多少净边。</li><li>出处：Cont, Kukanov and Stoikov, 2014；深度与价格压力见 Harris, <em>Trading and Exchanges</em>；限价簿状态见本站 <a href="/quant/lob-structure">LOB 结构</a>。</li></ul>',2))])}const c=B(p,[["render",I]]);export{q as __pageData,c as default};
